package com.eventaccess.platform.service;
import com.eventaccess.platform.domain.Enums.*;import com.eventaccess.platform.repository.*;import com.eventaccess.platform.security.AppPrincipal;import org.springframework.stereotype.Service;import java.math.BigDecimal;
@Service public class DashboardService {private final EventRepository events;private final OrderRepository orders;private final TicketRepository tickets;private final CheckinRepository checkins;public DashboardService(EventRepository e,OrderRepository o,TicketRepository t,CheckinRepository c){events=e;orders=o;tickets=t;checkins=c;} public Summary summary(AppPrincipal p){var org=p.organizationId();return new Summary(orders.sumPaidByOrganization(org),events.countByOrganizationId(org),orders.countByOrganizationIdAndStatus(org,OrderStatus.PENDING_PAYMENT),tickets.countByEventOrganizationId(org),tickets.countByEventOrganizationIdAndStatus(org,TicketStatus.USED),tickets.countByEventOrganizationIdAndStatus(org,TicketStatus.VALID),checkins.countByEventOrganizationIdAndResult(org,CheckinResult.ALREADY_USED));} public record Summary(BigDecimal revenue,long events,long pendingOrders,long issuedTickets,long present,long absent,long duplicateAttempts){} }
